source("R/simulation_design.R")
# Portable October 13 replication. Run from the repository root; see docs/SIMULATIONS.txt.
## Rerun 2026-09-30 (v2): constrained M-step in EM; a CAPPED direct comparator (constrOptim under the same |X beta| <= atanh(0.995)) added so that both methods optimize the same feasible set; the high-rate design is labelled by its realized mean true rate.
## Part O: algorithmic comparator. Direct quasi-Newton maximization (BFGS, numerical gradients) of the SAME
## Kalman-filter log-likelihood that EM maximizes, on (beta, a1, log P1, log sigma_eta2, log sigma_eps2).
## Not a different statistical model: the comparison is about optimum reached, iterations, time and failures.
## Designs: (i) base design N=150, T=30 with r = 1 and 4 (Part E); (ii) high recovery rate (mean phi 0.97, Part K
## regime) where the safeguard matters; (iii) the application windows with r free and with r fixed at 0.
source("R/state_space_em.R"); suppressPackageStartupMessages(library(parallel)); source("scripts/simulation/helpers/independent_generators.R")
negll <- function(par, y, X, fix_r = NULL) { p <- ncol(X); beta <- par[1:p]; a1 <- par[p + 1]; P1 <- exp(par[p + 2]); q <- exp(par[p + 3]); r <- if (is.null(fix_r)) exp(par[p + 4]) else fix_r
  phi <- as.vector(tanh(X %*% beta)); kf <- kalman_run(y, phi, 0, a1, P1, q, r); Fv <- kf$P_pred + r; e <- y - kf$alpha_pred; v <- 0.5 * sum(log(2 * pi * Fv) + e^2 / Fv); if (is.finite(v)) v else 1e300 }
direct <- function(y, X, start, fix_r = NULL, cap = NULL) { t0 <- Sys.time(); p <- ncol(X)
  if (is.null(cap)) o <- optim(start, negll, y = y, X = X, fix_r = fix_r, method = "BFGS", control = list(maxit = 5000, reltol = 1e-12)) else {   # same linear constraints |X beta| <= atanh(cap) as the EM safeguard
    bound <- atanh(cap); ui <- cbind(rbind(-X, X), matrix(0, 2 * nrow(X), length(start) - p)); ci <- rep(-bound, 2 * nrow(X)); st <- start; m <- max(abs(X %*% st[1:p])); if (m >= bound) st[1:p] <- st[1:p] * (0.999 * bound / m)
    o <- tryCatch(constrOptim(st, function(z) negll(z, y, X, fix_r), function(z) numDeriv::grad(function(u) negll(u, y, X, fix_r), z), ui = ui, ci = ci, method = "BFGS", outer.iterations = 100, outer.eps = 1e-8, control = list(maxit = 2000, reltol = 1e-10)), error = function(e) list(par = st, value = negll(st, y, X, fix_r), convergence = 99, counts = c(NA, NA))) }
  list(beta = o$par[1:p], a1 = o$par[p + 1], P1 = exp(o$par[p + 2]), sigma_eta2 = exp(o$par[p + 3]), sigma_eps2 = if (is.null(fix_r)) exp(o$par[p + 4]) else fix_r, loglik = -o$value, conv = o$convergence == 0, evals = o$counts[1], secs = as.numeric(Sys.time() - t0, units = "secs"), max_phi = max(abs(tanh(X %*% o$par[1:p])))) }
em <- function(y, X, init, fix_r = NULL) { t0 <- Sys.time(); f <- em_regression_mv(y, X, 0, init, thres = 1e-9, max_iter = 5000, fix_sigma_eps2 = fix_r); f$secs <- as.numeric(Sys.time() - t0, units = "secs"); f }
one <- function(m, design) { set.seed(70000 + m); if (design$kind == "base") { X <- generate_covariates(150); d <- generate_data_mv(X, design$beta, 30, 0, 7, 15, 1, design$r); y <- d$y } else { X <- generate_covariates(150); d <- generate_data_mv(X, design$beta, 30, 0, 7, 15, 1, design$r); y <- d$y }
  init <- list(beta = c(atanh(0.5), rep(0, ncol(X) - 1)), a1 = mean(y[, 1]), P1 = var(y[, 1]), sigma_eta2 = 1, sigma_eps2 = 1); start <- c(init$beta, init$a1, log(init$P1), log(init$sigma_eta2), log(init$sigma_eps2))
  fe <- em(y, X, init); fd <- direct(y, X, start); fc <- direct(y, X, start, cap = 0.995)
  c(ll_em = fe$loglik, ll_direct = fd$loglik, dll = fd$loglik - fe$loglik, dbeta = max(abs(fd$beta - fe$beta)), dr = fd$sigma_eps2 - fe$sigma_eps2, em_iter = fe$iter, em_conv = fe$converged, em_cap = isTRUE(fe$at_cap), em_stalled = identical(fe$status, "stalled"), em_secs = fe$secs, d_evals = fd$evals, d_conv = fd$conv, d_cap = fd$max_phi >= 0.999, d_secs = fd$secs, bias_em = fe$beta[4] - design$beta[4], bias_d = fd$beta[4] - design$beta[4], ll_capped = fc$loglik, dll_capped = fc$loglik - fe$loglik, capped_conv = fc$conv, capped_secs = fc$secs, bias_capped = fc$beta[4] - design$beta[4], mean_true_phi = mean(tanh(X %*% design$beta))) }
designs <- list(base_r1 = list(kind = "base", beta = c(0.3, 0.15, -0.2, 0.25), r = 1), base_r4 = list(kind = "base", beta = c(0.3, 0.15, -0.2, 0.25), r = 4), highphi = list(kind = "base", beta = c(atanh(0.97), 0.15, -0.2, 0.25), r = 1))
rows <- list(); for (k in names(designs)) { M <- if (k == "highphi") 50 else 100; res <- do.call(rbind, mclapply(seq_len(M), function(m) one(m, designs[[k]]), mc.cores = as.integer(Sys.getenv("SIM_CORES", "1")))); res <- as.data.frame(res)
  rows[[k]] <- data.frame(design = k, M = M, mean_true_phi = mean(res$mean_true_phi), same_optimum = mean(abs(res$dll) < 1e-3), direct_better_by_gt_1 = sum(res$dll > 1), em_better_by_gt_1 = sum(res$dll < -1), max_abs_dll = max(abs(res$dll)), max_dbeta = max(res$dbeta), em_median_iter = median(res$em_iter), em_nonconv = sum(res$em_conv == 0), em_cap = sum(res$em_cap == 1), em_stalled = sum(res$em_stalled == 1), em_median_secs = median(res$em_secs), direct_median_evals = median(res$d_evals), direct_nonconv = sum(res$d_conv == 0), direct_cap = sum(res$d_cap == 1), direct_median_secs = median(res$d_secs), bias_em = mean(res$bias_em), bias_direct = mean(res$bias_d), sd_em = sd(res$bias_em), sd_direct = sd(res$bias_d), capped_same_optimum = mean(abs(res$dll_capped) < 1e-3), capped_better_by_gt_0.01 = sum(res$dll_capped > 0.01), em_better_than_capped_by_gt_0.01 = sum(res$dll_capped < -0.01), max_abs_dll_capped = max(abs(res$dll_capped)), capped_nonconv = sum(res$capped_conv == 0), capped_median_secs = median(res$capped_secs), bias_capped = mean(res$bias_capped), sd_capped = sd(res$bias_capped))
  cat(k, ": "); print(rows[[k]], digits = 3, row.names = FALSE) }
## application
f <- pss_simulation_design("positive"); Y <- f$Y; X <- f$Xmat; init <- list(beta = f$truth$beta, a1 = mean(Y[, 1]), P1 = var(Y[, 1]), sigma_eta2 = 35, sigma_eps2 = 0); s0 <- c(init$beta, init$a1, log(init$P1), log(init$sigma_eta2))
fe0 <- em(Y, X, init, fix_r = 0); fd0 <- direct(Y, X, s0, fix_r = 0); cat(sprintf("application, r fixed at 0: EM loglik %.4f (%d iter, %.1f s) | direct %.4f (%d evals, %.1f s) | max |beta diff| %.1e\n", fe0$loglik, fe0$iter, fe0$secs, fd0$loglik, fd0$evals, fd0$secs, max(abs(fd0$beta - fe0$beta))))
fdf <- direct(Y, X, c(s0, log(100))); fef <- em(Y, X, modifyList(init, list(sigma_eps2 = 100))); cat(sprintf("application, r free: direct -> sigma_eps2 %.3g, loglik %.4f, conv %s (%d evals, %.0f s) | EM (max 5000 it.) -> sigma_eps2 %.3g, loglik %.4f, conv %s (%.0f s)\n", fdf$sigma_eps2, fdf$loglik, fdf$conv, fdf$evals, fdf$secs, fef$sigma_eps2, fef$loglik, fef$converged, fef$secs))
app <- data.frame(design = c("application r=0", "application r free"), M = 1, mean_true_phi = NA, same_optimum = c(abs(fd0$loglik - fe0$loglik) < 1e-3, NA), direct_better_by_gt_1 = NA, em_better_by_gt_1 = NA, max_abs_dll = c(abs(fd0$loglik - fe0$loglik), fdf$loglik - fef$loglik), max_dbeta = c(max(abs(fd0$beta - fe0$beta)), max(abs(fdf$beta - fef$beta))), em_median_iter = c(fe0$iter, fef$iter), em_nonconv = c(!fe0$converged, !fef$converged), em_cap = c(isTRUE(fe0$at_cap), isTRUE(fef$at_cap)), em_median_secs = c(fe0$secs, fef$secs), direct_median_evals = c(fd0$evals, fdf$evals), direct_nonconv = c(!fd0$conv, !fdf$conv), direct_cap = c(fd0$max_phi >= 0.999, fdf$max_phi >= 0.999), direct_median_secs = c(fd0$secs, fdf$secs), bias_em = NA, bias_direct = NA, sd_em = NA, sd_direct = NA, em_stalled = c(identical(fe0$status, "stalled"), identical(fef$status, "stalled")), capped_same_optimum = NA, capped_better_by_gt_0.01 = NA, em_better_than_capped_by_gt_0.01 = NA, max_abs_dll_capped = NA, capped_nonconv = NA, capped_median_secs = NA, bias_capped = NA, sd_capped = NA)
tab <- rbind(do.call(rbind, rows), app); write.csv(tab, "results/simulation/tables/part_o_direct_optimization_v2.csv", row.names = FALSE); saveRDS(list(app = list(em0 = fe0, d0 = fd0, dfree = fdf, efree = fef)), "results/simulation/tables/part_o_direct_optimization_v2_raw.rds"); cat("saved\n")
